// 编写日期：2026年8月5日
// 作者：zidong
// 程序说明：图书管理系统 - 主程序（注册/登录 + 菜单交互）

#include <iostream>
#include <string>
#include <vector>
#include "book.hpp"
#include "user.hpp"
#include "admin.hpp"

using std::cin;
using std::cout;
using std::endl;
using std::string;
using std::vector;

// 从用户列表查找索引；未找到返回 -1
int findUser(const vector<User>& users, const string& name) {
    for (size_t i = 0; i < users.size(); ++i) {
        if (users[i].getUsername() == name) return int(i);
    }
    return -1;
}

// 从管理员列表查找索引；未找到返回 -1
int findAdmin(const vector<Admin>& admins, const string& name) {
    for (size_t i = 0; i < admins.size(); ++i) {
        if (admins[i].getUsername() == name) return int(i);
    }
    return -1;
}

// 从图书列表查找索引；未找到返回 -1
int findBook(const vector<Book>& books, const string& id) {
    for (size_t i = 0; i < books.size(); ++i) {
        if (books[i].getId() == id) return int(i);
    }
    return -1;
}

// 显示当前所有图书
void showBooks(const vector<Book>& books) {
    if (books.empty()) {
        cout << "（当前没有图书）" << endl;
        return;
    }
    cout << "------ 图书列表 ------" << endl;
    for (size_t i = 0; i < books.size(); ++i) {
        books[i].print();
    }
    cout << "----------------------" << endl;
}

// 浏览并借阅图书（用户功能）
void borrowBooks(vector<Book>& books, User& user) {
    if (books.empty()) {
        cout << "当前没有任何图书可借。" << endl;
        return;
    }
    showBooks(books);
    cout << "请输入要借阅的图书编号（输入 q 取消）：";
    string id;
    cin >> id;
    if (id == "q") return;

    int idx = findBook(books, id);
    if (idx == -1) {
        cout << "未找到该图书。" << endl;
        return;
    }
    if (user.hasBorrowed(id)) {
        cout << "您已借阅过这本书，不能重复借阅。" << endl;
        return;
    }
    if (books[idx].getStock() <= 0) {
        cout << "该书当前无库存，无法借阅。" << endl;
        return;
    }
    books[idx].borrowOne();       // 库存减一
    user.borrowBook(id);          // 记录借阅
    cout << "借阅成功：《" << books[idx].getName() << "》" << endl;
}

// 归还图书（用户功能）
void returnBooks(vector<Book>& books, User& user) {
    if (user.borrowedCount() == 0) {
        cout << "您当前没有借阅任何图书。" << endl;
        return;
    }
    cout << "您当前已借阅：" << endl;
    const vector<string>& ids = user.getBorrowedIds();
    for (size_t i = 0; i < ids.size(); ++i) {
        int bi = findBook(books, ids[i]);
        if (bi != -1) {
            cout << "  - " << ids[i] << "：《" << books[bi].getName() << "》" << endl;
        } else {
            cout << "  - " << ids[i] << endl;
        }
    }
    cout << "请输入要归还的图书编号（输入 q 取消）：";
    string id;
    cin >> id;
    if (id == "q") return;

    if (user.returnBook(id)) {        // 移除借阅记录
        int bi = findBook(books, id);
        if (bi != -1) {
            books[bi].returnOne();    // 库存加一
            cout << "归还成功：" << id << endl;
        } else {
            cout << "归还成功（该书已不在馆藏列表中）。" << endl;
        }
    } else {
        cout << "归还失败：您没有借阅该书。" << endl;
    }
}

// 用户主菜单
void userMenu(vector<Book>& books, User& user) {
    while (true) {
        cout << "\n===== 用户菜单：《" << user.getUsername()
             << "》 已登录 =====" << endl;
        cout << "1. 查看图书列表" << endl;
        cout << "2. 借阅图书" << endl;
        cout << "3. 归还图书" << endl;
        cout << "4. 查看我的借阅" << endl;
        cout << "5. 退出登录" << endl;
        cout << "请选择：";
        int choice;
        cin >> choice;

        if (choice == 1) {
            showBooks(books);
        } else if (choice == 2) {
            borrowBooks(books, user);
        } else if (choice == 3) {
            returnBooks(books, user);
        } else if (choice == 4) {
            if (user.borrowedCount() == 0) {
                cout << "您当前没有借阅任何图书。" << endl;
            } else {
                const vector<string>& ids = user.getBorrowedIds();
                cout << "我借阅的图书：" << endl;
                for (size_t i = 0; i < ids.size(); ++i) {
                    int bi = findBook(books, ids[i]);
                    if (bi != -1) {
                        cout << "  - " << ids[i] << "：《" << books[bi].getName() << "》" << endl;
                    }
                }
            }
        } else if (choice == 5) {
            cout << "已退出登录。" << endl;
            break;
        } else {
            cout << "无效选项，请重新输入。" << endl;
        }
    }
}

// 管理员主菜单
void adminMenu(vector<Book>& books, const Admin& admin) {
    while (true) {
        cout << "\n===== 管理员菜单：《" << admin.getUsername()
             << "》 已登录 =====" << endl;
        cout << "1. 查看图书列表" << endl;
        cout << "2. 图书入库" << endl;
        cout << "3. 图书出库" << endl;
        cout << "4. 退出登录" << endl;
        cout << "请选择：";
        int choice;
        cin >> choice;

        if (choice == 1) {
            showBooks(books);
        } else if (choice == 2 || choice == 3) {
            if (choice == 2) {
                cout << "（图书入库）" << endl;
            } else {
                cout << "（图书出库）" << endl;
            }
            cout << "请输入图书编号：";
            string id;
            cin >> id;
            string bname;
            if (choice == 2) {
                cout << "请输入书名：";
                cin >> bname;
            }
            cout << "请输入数量：";
            int count;
            cin >> count;
            if (count < 0) {
                cout << "数量不能为负数。" << endl;
                continue;
            }
            if (choice == 2) {
                Admin::addBook(books, id, bname, count);   // 入库
            } else {
                Admin::removeBook(books, id, count);       // 出库
            }
        } else if (choice == 4) {
            cout << "已退出登录。" << endl;
            break;
        } else {
            cout << "无效选项，请重新输入。" << endl;
        }
    }
}

int main() {
    vector<Book> books;      // 图书集合
    vector<User> users;      // 用户列表
    vector<Admin> admins;    // 管理员列表

    // 预置一个默认管理员账号 admin/admin123
    admins.push_back(Admin("admin", "admin123"));

    while (true) {
        cout << "\n========= 图书管理系统 =========" << endl;
        cout << "1. 注册" << endl;
        cout << "2. 登录" << endl;
        cout << "3. 退出系统" << endl;
        cout << "请选择：";
        int choice;
        cin >> choice;

        if (choice == 1) {
            // ---- 注册 ----
            cout << "注册为：1. 管理员  2. 用户" << endl;
            int role;
            cin >> role;
            cout << "请输入用户名：";
            string name;
            cin >> name;
            cout << "请输入密码：";
            string pwd;
            cin >> pwd;

            if (role == 1) {
                if (findAdmin(admins, name) != -1) {
                    cout << "该管理员用户名已存在，注册失败。" << endl;
                } else {
                    admins.push_back(Admin(name, pwd));
                    cout << "管理员注册成功！" << endl;
                }
            } else if (role == 2) {
                if (findUser(users, name) != -1) {
                    cout << "该用户名已存在，注册失败。" << endl;
                } else {
                    users.push_back(User(name, pwd));
                    cout << "用户注册成功！" << endl;
                }
            } else {
                cout << "无效的注册类型。" << endl;
            }
        } else if (choice == 2) {
            // ---- 登录 ----
            cout << "登录为：1. 管理员  2. 用户" << endl;
            int role;
            cin >> role;
            cout << "请输入用户名：";
            string name;
            cin >> name;
            cout << "请输入密码：";
            string pwd;
            cin >> pwd;

            if (role == 1) {
                int ai = findAdmin(admins, name);
                if (ai == -1) {
                    cout << "该管理员不存在。" << endl;
                } else if (admins[ai].getPassword() != pwd) {
                    cout << "密码错误！" << endl;
                } else {
                    cout << "登录成功！欢迎，管理员 " << name << endl;
                    adminMenu(books, admins[ai]);
                }
            } else if (role == 2) {
                int ui = findUser(users, name);
                if (ui == -1) {
                    cout << "该用户不存在。" << endl;
                } else if (users[ui].getPassword() != pwd) {
                    cout << "密码错误！" << endl;
                } else {
                    cout << "登录成功！欢迎，" << name << endl;
                    userMenu(books, users[ui]);
                }
            } else {
                cout << "无效的登录类型。" << endl;
            }
        } else if (choice == 3) {
            cout << "感谢使用图书管理系统，再见！" << endl;
            break;
        } else {
            cout << "无效选项，请重新输入。" << endl;
        }
    }

    return 0;
}
